W,H = 14,15
g = [[0]*W for _ in range(H)]
walls = {2:[4], 4:[2,7,11], 7:[2,9], 10:[4,7,11]}
m = 6
g[0][m] = 2
wall_rows = sorted(walls)
# bars above each wall, widths 5,11,17,23... centered at m, clipped
for i,wr in enumerate(wall_rows):
    wdt = 6*i+5
    l = m - wdt//2; r = l + wdt - 1
    l = max(0,l); r = min(W-1,r)
    for c in range(l,r+1): g[wr-1][c] = 2
# verticals through every gap
for i,wr in enumerate(wall_rows):
    nxt = wall_rows[i+1]-1 if i+1 < len(wall_rows) else H-1  # next bar row or bottom
    for c in walls[wr]:
        for r in range(wr, nxt+1): g[r][c] = 2
# restore walls (8s) except gap cells
for wr,gaps in walls.items():
    for c in range(W):
        g[wr][c] = 0 if c in gaps else 8
for row in g: print(row)
